def _slot_kind_value(slot: dict[str, Any]) -> str:
    return str(slot.get("slot_kind") or "").strip().lower()


def _slot_sleeve_profile(slot: dict[str, Any]) -> str:
    explicit = str(slot.get("sleeve_profile") or "").strip().lower()
    if explicit:
        return explicit
    kind = _slot_kind_value(slot)
    if "day_trading" in kind:
        return "day_trading"
    if "aggressive_intraday" in kind or "intraday" in kind:
        return "intraday_aggressive"
    if "dividend_capture" in kind or "ex_dividend" in kind:
        return "dividend_capture"
    if "dividend" in kind or "reit" in kind or "covered_call_income" in kind:
        return "dividend_income"
    return ""


def _slot_sleeve_family(slot: dict[str, Any]) -> str:
    explicit = str(slot.get("sleeve_family") or "").strip().lower()
    if explicit:
        return explicit
    sleeve_profile = _slot_sleeve_profile(slot)
    if sleeve_profile in {"intraday_aggressive", "day_trading"}:
        return "intraday"
    if sleeve_profile.startswith("dividend"):
        return "dividend"
    return ""


