def _quant_slot(
    *,
    bot_id: str,
    sleeve_profile: str,
    slot_label: str,
    slot_kind: str,
    priority: str,
    objective: str,
    preferred_regimes: list[str],
    bootstrap_teacher_bot_ids: list[str],
    rationale: str,
    data_intake_extra: list[str] | None = None,
    storage_extra: list[str] | None = None,
    correlation_peers: list[str] | None = None,
    bot_role: str = "signal_sub_bot",
    target_functions_extra: list[str] | None = None,
) -> dict[str, Any]:
    peers = ordered_unique(list(correlation_peers or []) + QUANT_MODEL_CORRELATION_PEERS)
    return {
        "bot_id": bot_id,
        "bot_role": bot_role,
        "sleeve_profile": sleeve_profile,
        "sleeve_family": "quant_models",
        "slot_label": slot_label,
        "slot_kind": slot_kind,
        "priority": priority,
        "objective": objective,
        "target_functions": ordered_unique(
            [
                "quant_model_control",
                "market_correlation_sync",
                "paper_execution_calibration",
                "training_label_audit",
                "risk_service",
            ]
            + list(target_functions_extra or [])
        ),
        "preferred_regimes": preferred_regimes,
        "bootstrap_teacher_bot_ids": bootstrap_teacher_bot_ids,
        "data_intake_collections": ordered_unique(QUANT_MODEL_COLLECTIONS + list(data_intake_extra or [])),
        "storage_targets": ordered_unique(QUANT_MODEL_STORAGE_TARGETS + list(storage_extra or [])),
        "correlation_peer_sleeves": peers,
        "correlation_dependencies": [
            "cross_sleeve_correlation_matrix",
            "model_price_sensitivity_grid",
            "tail_risk_surface",
            "state_filter_diagnostics",
            "resource_profile",
        ],
        "label_contract": _quant_label_contract(slot_kind, sleeve_profile),
        "rationale": rationale,
    }


def _exotic_slot(
    *,
    bot_id: str,
    sleeve_profile: str,
    slot_label: str,
    slot_kind: str,
    priority: str,
    objective: str,
    preferred_regimes: list[str],
    bootstrap_teacher_bot_ids: list[str],
    rationale: str,
    data_intake_extra: list[str] | None = None,
    storage_extra: list[str] | None = None,
    correlation_peers: list[str] | None = None,
    bot_role: str = "options_sub_bot",
    include_options_context: bool = True,
    target_functions_extra: list[str] | None = None,
) -> dict[str, Any]:
    peers = ordered_unique(list(correlation_peers or []) + EXOTIC_DERIVATIVE_CORRELATION_PEERS)
    target_functions = [
        "market_correlation_sync",
        "macro_bulletin",
        "paper_execution_calibration",
        "risk_service",
        "exotic_derivative_context_sync",
    ]
    if include_options_context:
        target_functions.insert(0, "collect_options_flow_context")
    target_functions = ordered_unique(target_functions + list(target_functions_extra or []))
    return {
        "bot_id": bot_id,
        "bot_role": bot_role,
        "sleeve_profile": sleeve_profile,
        "sleeve_family": "exotic_derivatives",
        "slot_label": slot_label,
        "slot_kind": slot_kind,
        "priority": priority,
        "objective": objective,
        "target_functions": target_functions,
        "preferred_regimes": preferred_regimes,
        "bootstrap_teacher_bot_ids": bootstrap_teacher_bot_ids,
        "data_intake_collections": ordered_unique(
            EXOTIC_DERIVATIVE_CORRELATION_COLLECTIONS + list(data_intake_extra or [])
        ),
        "storage_targets": ordered_unique(EXOTIC_DERIVATIVE_STORAGE_TARGETS + list(storage_extra or [])),
        "correlation_peer_sleeves": peers,
        "correlation_dependencies": [
            "cross_sleeve_exposure_netting",
            "correlation_cluster_risk",
            "rates_credit_macro",
            "futures_curve_context",
            "options_vol_surface",
        ],
        "rationale": rationale,
    }


