def _slot_storage_targets(slot: dict[str, Any]) -> list[str]:
    requested = [str(item or "").strip() for item in list(slot.get("storage_targets") or [])]
    targets: list[str] = [item for item in requested if item]
    role = str(slot.get("bot_role") or "")
    kind = _slot_kind_value(slot)
    sleeve_profile = _slot_sleeve_profile(slot)
    target_functions = {str(item or "").strip() for item in list(slot.get("target_functions") or [])}
    targets.extend(
        [
            "governance/training_diagnostics",
            "governance/walk_forward",
            "data/jsonl_link.sqlite3",
            "data/bot_channel_queue.sqlite3",
        ]
    )
    if role == "options_sub_bot" or "options" in kind or "collect_options_flow_context" in target_functions:
        targets.extend(["exports/options_flow", "exports/external_context/options_flow", "governance/options_flow"])
