def _slot_freshness_slo_seconds(slot: dict[str, Any]) -> int:
    raw = slot.get("freshness_slo_seconds")
    if raw not in {None, ""}:
        return max(_safe_int(raw, 300), 30)
    role = str(slot.get("bot_role") or "")
    kind = _slot_kind_value(slot)
    sleeve_profile = _slot_sleeve_profile(slot)
    if sleeve_profile == "intraday_aggressive" or "aggressive_intraday" in kind:
        return 60
    if sleeve_profile == "day_trading" or "day_trading" in kind:
        return 90
    if _is_quant_model_kind(kind) or sleeve_profile in QUANT_MODEL_SLEEVE_PROFILES:
        return 300
    if _is_exotic_derivative_kind(kind):
        return 300
    if role == "options_sub_bot" or "options" in kind:
        return 180
    if "macro" in kind or "event" in kind:
        return 300
    return 900


def _slot_retention_profile(slot: dict[str, Any]) -> str:
    raw = str(slot.get("retention_profile") or "").strip()
    if raw:
        return raw
    kind = _slot_kind_value(slot)
    role = str(slot.get("bot_role") or "")
    sleeve_profile = _slot_sleeve_profile(slot)
    if sleeve_profile in {"intraday_aggressive", "day_trading"} or "aggressive_intraday" in kind:
        return "hot_intraday_7d_warm_90d"
    if _is_quant_model_kind(kind) or sleeve_profile in QUANT_MODEL_SLEEVE_PROFILES:
        return "hot_quant_research_14d_warm_365d"
    if _is_exotic_derivative_kind(kind):
        return "hot_exotic_derivatives_14d_warm_365d"
    if role == "options_sub_bot" or "options" in kind:
        return "hot_options_14d_warm_180d"
    return "standard_candidate_30d_warm_180d"


def _slot_training_thresholds(slot: dict[str, Any]) -> tuple[int, int]:
    kind = _slot_kind_value(slot)
    role = str(slot.get("bot_role") or "")
    sleeve_profile = _slot_sleeve_profile(slot)
    if sleeve_profile == "intraday_aggressive" or "aggressive_intraday" in kind:
        return 5000, 5
    if sleeve_profile == "day_trading" or "day_trading" in kind:
        return 4000, 5
    if _is_quant_model_kind(kind) or sleeve_profile in QUANT_MODEL_SLEEVE_PROFILES:
        return 3000, 14
    if _is_exotic_derivative_kind(kind):
        return 2500, 14
    if role == "options_sub_bot" or "options" in kind:
        return 1500, 7
    return 1000, 7


